providerResponses.text:
{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can explain why current and potential difference are distinct, justify conservation rules in a circuit from those ideas, and correctly solve a changed circuit problem independently."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I confuse current with potential difference and cannot explain why circuit rules hold. Prepare for independent problem solving.",
          "explanation": "The reported weakness is conceptual: current and potential difference are conflated, so the conservation rules feel like arbitrary facts. The smallest useful strategy is one integrated conceptual activity that separates the two quantities and derives the circuit rules from them, followed by one independent changed problem to confirm the learner can apply the distinction without support. No separate relearning set or repeated check is booked because there is no observed failure yet; further remediation is contingent on the independent problem revealing a specific error.",
          "recommendedEffort": {
            "lowMinutes": 60,
            "likelyMinutes": 90,
            "highMinutes": 120
          },
          "phases": [
            {
              "localId": "concept",
              "title": "Separate current and potential difference, then derive circuit rules",
              "outcome": "Explain the distinction between current and potential difference and use it to justify conservation of charge and energy in circuits.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 60
              },
              "readinessCriterion": "Correctly explain, in your own words, why current is not 'used up' around a series loop while potential difference is divided across components."
            },
            {
              "localId": "apply",
              "title": "Independent circuit problem solving",
              "outcome": "Solve a changed circuit problem correctly by choosing and applying the appropriate conservation rule.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 60
              },
              "readinessCriterion": "Correctly solve a changed circuit problem, stating which conservation rule applies and why."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Core conceptual target: distinguish current (rate of charge flow) from potential difference (energy per unit charge), which is the reported confusion."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Derive conservation of charge (junction rule) and conservation of energy (loop rule) from the current/potential distinction so the rules are explained, not memorized."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Apply the concepts to a changed circuit problem to confirm independent problem-solving capability."
          }
        ],
        "activities": [
          {
            "localId": "concept_build",
            "outcomeRefs": [
              "concept"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Build the current vs potential difference distinction and derive circuit conservation rules",
            "activityType": "Guided conceptual explanation with worked examples",
            "purpose": "Replace the current/potential conflation with a correct model and use it to explain why the circuit rules hold.",
            "instructions": "1) Write one sentence each defining current and potential difference, including their units and what each measures. 2) For a simple series circuit with a battery and two resistors, trace the current around the loop and mark the potential difference across each component. Explain why the current is the same at every point but the potential differences add to the battery voltage. 3) For a parallel branch, explain why the potential difference is the same across branches but the currents split. 4) State the junction rule (conservation of charge) and the loop rule (conservation of energy) and, for each, explain in your own words how it follows from your definitions in step 1. 5) Check your explanations against a textbook or notes and correct any statement that treats current as something 'used up' or potential difference as a flow.",
            "completionCriterion": "You have written definitions of current and potential difference, traced current and potential difference in one series and one parallel example, and stated both conservation rules with a correct derivation from your definitions.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 60
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "independent_problem",
            "outcomeRefs": [
              "apply"
            ],
            "scopeRefs": [
              "scope_3"
            ],
            "title": "Solve a changed circuit problem independently",
            "activityType": "Independent problem solving",
            "purpose": "Confirm the learner can choose and apply the correct conservation rule on unfamiliar work without assistance.",
            "instructions": "Solve one circuit problem you have not seen before that requires both the junction rule and the loop rule (for example, a two-loop circuit with given resistances and a battery). Do not look at a worked solution first. For each step, write which conservation rule you are using and why it applies. After finishing, check your numerical answers by substituting them back into the rules; if an answer is wrong, identify the specific conceptual or algebraic error and correct it.",
            "completionCriterion": "The problem is solved correctly, each rule used is named with a valid reason, and any error found on checking is corrected with an explanation of the cause.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 60
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [
              "concept_build"
            ]
          },
          {
            "localId": "targeted_remediation",
            "outcomeRefs": [
              "apply"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3"
            ],
            "title": "Targeted remediation on the specific error from the independent problem",
            "activityType": "Focused re-explanation and corrected practice",
            "purpose": "Address only the concrete conceptual or procedural error observed in the independent problem, if one occurs.",
            "instructions": "Re-read your independent problem work and identify the exact step where the error occurred. Re-explain the relevant concept (current vs potential difference, junction rule, or loop rule) in your own words, then redo only that step and any downstream steps affected. Finish by stating what you will check first next time to avoid the same error.",
            "completionCriterion": "The specific error is explained, the affected step is redone correctly, and you state a concrete check to prevent recurrence.",
            "effort": {
              "lowMinutes": 15,
              "likelyMinutes": 25,
              "highMinutes": 40
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "independent_problem",
                "condition": "The independent problem is not solved correctly, or a rule is applied with an invalid reason, or a conceptual error about current vs potential difference appears."
              }
            },
            "hardDependencies": [
              "independent_problem"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has access to a textbook or notes for checking the conceptual explanations.",
            "No prior demonstrated readiness exists for any scope node, so all three are treated as new learning."
          ],
