{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can explain Bayes' rule in your own words, correctly compute the posterior probability in a changed medical-test example (different base rate, sensitivity and false-positive rate), and state why the base rate matters — with no base-rate/sensitivity confusion."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "MASTERY",
          "outcome": "Develop the ability to explain Bayes' rule and apply it to a changed medical-test probability example. I confuse the base rate with sensitivity.",
          "explanation": "The reported weakness is a specific conceptual confusion: treating the base rate (prevalence) as if it were the sensitivity (true-positive rate). Mastery here needs three things: a correct mental model of conditional probability and base rates, fluent use of Bayes' rule, and independent transfer to an unfamiliar medical-test example. Because the confusion is conceptual rather than a missing procedure, the efficient path is one integrated explanation-and-application activity that directly contrasts base rate with sensitivity, followed by one independent changed-example task that certifies transfer. A separate relearning block, multiple practice sets and a second full check would duplicate evidence already produced by the integrated task and the transfer task, so they are left contingent on an observed failure rather than booked. No deadline exists, so the checkpoint is set at 14 days, which is ample for a single focused concept at 60 minutes/day.",
          "recommendedEffort": {
            "lowMinutes": 90,
            "likelyMinutes": 150,
            "highMinutes": 240
          },
          "phases": [
            {
              "localId": "phase_model",
              "title": "Correct model of base rates and conditional probability",
              "outcome": "You can distinguish base rate (prevalence) from sensitivity (true-positive rate) and explain how each enters a conditional probability statement.",
              "effort": {
                "lowMinutes": 40,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
              "readinessCriterion": "You correctly label base rate and sensitivity in a worked medical-test setup and explain in your own words why a low base rate can make a positive test result less informative than intuition suggests."
            },
            {
              "localId": "phase_bayes",
              "title": "Fluent application of Bayes' rule",
              "outcome": "You can set up and compute a posterior probability with Bayes' rule from a base rate, sensitivity and false-positive rate.",
              "effort": {
                "lowMinutes": 40,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
              "readinessCriterion": "You compute the posterior probability correctly in a worked example and show the numerator and denominator explicitly."
            },
            {
              "localId": "phase_transfer",
              "title": "Independent transfer to a changed example",
              "outcome": "You correctly solve an unfamiliar medical-test probability problem using Bayes' rule without assistance.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 60
              },
              "readinessCriterion": "You produce the correct posterior probability for a changed example (different base rate, sensitivity and false-positive rate) and justify each term you substituted."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Provides the conceptual foundation: distinguishing base rate from sensitivity and reading conditional probability statements correctly, which is the exact point of the reported confusion."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Provides the computational procedure (Bayes' rule) that turns the corrected model into a usable method for medical-test problems."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Certifies transfer: solving a changed medical-test example independently is the evidence that the base-rate/sensitivity confusion is resolved rather than merely recognized."
          }
        ],
        "activities": [
          {
            "localId": "integrated_bayes",
            "outcomeRefs": [
              "phase_model",
              "phase_bayes"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Explain and apply Bayes' rule to a medical-test example, contrasting base rate with sensitivity",
            "activityType": "Integrated explanation and supported application",
            "purpose": "Directly repairs the base-rate/sensitivity confusion while building the Bayes' rule procedure, producing both explanatory and computational evidence in one pass.",
            "instructions": "Work through a single medical-test scenario, e.g. a disease with prevalence 1%, a test with sensitivity 90% and false-positive rate 5%. (1) Write down which number is the base rate and which is the sensitivity, and state in your own words what each means. (2) Write Bayes' rule for P(disease | positive test) and identify each term: prior, likelihood, and the two parts of the denominator (true positives and false positives). (3) Compute the posterior probability step by step, showing the numerator and denominator separately. (4) Explain why the posterior is much lower than the sensitivity, tying the answer to the low base rate. (5) Change only the base rate to 20% and recompute, then explain what changed and why. Keep your written work so you can compare it with the later transfer task.",
            "completionCriterion": "You have written the correct posterior for both the 1% and 20% base-rate versions, correctly labelled base rate and sensitivity, and given a correct explanation of why the low base rate keeps the posterior below the sensitivity.",
            "effort": {
              "lowMinutes": 45,
              "likelyMinutes": 60,
              "highMinutes": 90
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "transfer_check",
            "outcomeRefs": [
              "phase_transfer"
            ],
            "scopeRefs": [
              "scope_3"
            ],
            "title": "Independently solve a changed medical-test probability example",
            "activityType": "Independent transfer task",
            "purpose": "Certifies that the corrected model and the Bayes' rule procedure transfer to an unfamiliar example without assistance, which is the mastery evidence the outcome requires.",
            "instructions": "Without looking back at your earlier work, solve a new medical-test problem with a different base rate, sensitivity and false-positive rate (for example prevalence 4%, sensitivity 80%, false-positive rate 10%). Write Bayes' rule, substitute the values, compute the posterior, and state in one or two sentences what the result means for a patient who tests positive. Then check your arithmetic and, if you made an error, correct it and note what caused it.",
            "completionCriterion": "You produce the correct posterior probability for the changed example, show the substituted terms, and give a correct interpretation; any arithmetic error is found and corrected with a stated cause.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
