  "detail": {
    "days": 14,
    "checkpoint": "One uninterrupted 45-minute authentic circuit lab check completed and its measurements recorded, or an explicit disclosure that no 45-minute uninterrupted slot exists in the confirmed 30-minute daily availability."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "GENERAL",
