          "explanation": "The accepted requirement is a single indivisible 45-minute uninterrupted authentic lab check. Confirmed availability provides only 30 minutes per day with no recovery margin, so the honest committed duration cannot be reduced or split without invalidating the measurement. The correct educational response is to book the authentic task at its full 45-minute indivisible duration, disclose the allocation conflict, and keep any preparatory or alternative work optional rather than substituting it for the required check.",
          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 45,
            "highMinutes": 45
          },
          "phases": [
            {
              "localId": "phase_check",
              "title": "Authentic circuit lab check",
              "outcome": "One uninterrupted 45-minute authentic circuit lab check completed with valid measurements.",
              "effort": {
                "lowMinutes": 45,
                "likelyMinutes": 45,
                "highMinutes": 45
              },
              "readinessCriterion": "The full 45-minute uninterrupted check is completed in one sitting and its measurements are recorded."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The single required authentic task: one uninterrupted 45-minute circuit lab check whose measurements are valid only if the run is not interrupted."
          }
        ],
        "activities": [
          {
            "localId": "lab_check",
            "outcomeRefs": [
              "phase_check"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Complete the 45-minute uninterrupted authentic circuit lab check",
            "activityType": "Authentic lab check",
            "purpose": "Fulfil the accepted requirement by performing the authentic circuit lab check in one uninterrupted 45-minute sitting; this is the only activity that can produce the required valid measurements.",
            "instructions": "Set up the circuit and measurement equipment before starting the clock. Once the 45-minute run begins, do not pause, adjust, or restart the measurement, because any interruption invalidates the check. Record the measurements as they are taken and note the start and end times. If no uninterrupted 45-minute slot is available in the confirmed 30-minute daily availability, do not shorten or split the check; instead record that the required slot is unavailable and report the conflict.",
            "completionCriterion": "A single uninterrupted 45-minute authentic circuit lab check is completed and its measurements are recorded, or the absence of a 45-minute uninterrupted slot is explicitly reported without substituting a shorter check.",
            "effort": {
              "lowMinutes": 45,
              "likelyMinutes": 45,
              "highMinutes": 45
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "The required 45-minute indivisible check exceeds the confirmed 30-minute daily ceiling, so it cannot be scheduled within the current availability without either an uninterrupted 45-minute slot or an explicit conflict disclosure; no shorter or split substitute is offered because that would invalidate the check."
          ],
          "unresolvedUncertainty": [
            "Whether an uninterrupted 45-minute slot can be made available despite the confirmed 30-minute daily ceiling."
          ],
          "stoppingConditions": [
            "Stop once the 45-minute uninterrupted check is completed and its measurements are recorded, or once the absence of a 45-minute uninterrupted slot has been explicitly reported."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The accepted requirement is a single indivisible 45-minute uninterrupted authentic lab check, but confirmed availability provides only 30 minutes per day with no recovery margin. Reducing the check to 30 minutes or splitting it across days would invalidate the measurement, so the honest 45-minute committed duration is retained and the allocation conflict is disclosed rather than silently resolved. No preparatory or alternative activity is committed because none can substitute for the required authentic check; any such work would be optional and is therefore not booked."
}

