  "detail": {
    "days": 14,
    "checkpoint": "A working CSV expenses report that reads rows, groups totals by category, and detects and explains malformed rows, demonstrated on a changed data file without assistance."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Use my uploaded course note to build a small CSV expenses-report project. Verify quotations and course applicability; it is my development course note, not an official public syllabus.",
          "explanation": "The accepted outcome is a small working CSV expenses report covering three requested capabilities: reading rows, grouping totals by category, and detecting/explaining malformed rows. No prior execution history exists, so readiness is unknown; the source is a private development course note with no verified prerequisite recommendations. A single integrated build-and-demonstrate activity is the smallest useful strategy: it teaches the rule during work, solves and checks the actual report, and includes the required changed-data example. No separate relearning or repeated practice set is justified before any observed failure. Later engineering, tooling, or project milestones remain strategic and unbooked until this checkpoint is independently demonstrated.",
          "recommendedEffort": {
            "lowMinutes": 90,
            "likelyMinutes": 150,
            "highMinutes": 240
          },
          "phases": [
            {
              "localId": "phase_build",
              "title": "Build and demonstrate the CSV expenses report",
              "outcome": "A working report that reads CSV rows, groups totals by category, and detects and explains malformed rows, demonstrated on a changed data file without assistance.",
              "effort": {
                "lowMinutes": 90,
                "likelyMinutes": 150,
                "highMinutes": 240
              },
              "readinessCriterion": "The report runs on the original data and on a changed data file, produces correct category totals, and correctly identifies and explains at least one malformed row without assistance."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Reading CSV rows is the input step of the report; the activity must parse valid rows correctly, including quoted fields containing commas."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Grouping expense totals by category is the core report output; the activity must produce correct per-category totals on the original and changed data."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Handling malformed rows is a required course outcome; the activity must detect and explain malformed rows rather than silently excluding them."
          }
        ],
        "activities": [
          {
            "localId": "build_report",
            "outcomeRefs": [
              "phase_build"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3"
            ],
            "title": "Build and demonstrate the CSV expenses report",
            "activityType": "Integrated build-and-demonstrate project",
            "purpose": "Produce the accepted outcome in one integrated piece of work: read CSV rows, group totals by category, detect and explain malformed rows, and demonstrate correctness on a changed data file.",
            "instructions": "Using your uploaded course note as the reference, build a small CSV expenses report. 1) Read the expense CSV rows, parsing quoted fields correctly (a quoted comma is valid data, not a separator). 2) Group amounts by category and report each category total. 3) Detect malformed rows and explain each one rather than silently excluding it. 4) Run the report on the original data and check the totals and any malformed-row explanations against the data by hand. 5) Create a changed data file with different categories, amounts, and at least one malformed row, run the report on it, and verify the grouping and error handling independently. During the work, explain the rule you are applying at each step (parsing, grouping, malformed-row detection) so the reasoning is visible, and correct any actual errors you find. Stop when the report works correctly on both files and you can explain the malformed-row handling.",
            "completionCriterion": "The report runs on the original data and on a changed data file, produces correct category totals for both, and correctly identifies and explains at least one malformed row in the changed file without assistance.",
            "effort": {
              "lowMinutes": 90,
              "likelyMinutes": 150,
              "highMinutes": 240
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "splitPoints": [
              {
                "afterMinutes": 30,
                "completionCriterion": "CSV rows are read correctly, including quoted fields, and the report prints the parsed rows."
              },
              {
                "afterMinutes": 45,
                "completionCriterion": "Category totals are computed and printed correctly for the original data."
              }
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has basic familiarity with running a small script or program in some language, since no prerequisite recommendations were supplied.",
            "The uploaded course note is the authoritative reference for the required capabilities, but it is a private development note, not an official public syllabus."
          ],
          "tradeOffs": [
            "Only one integrated activity is committed; separate explanation, practice, and check stages are not booked because the integrated build-and-demonstrate task already covers explanation, supported application, and an independent changed example.",
            "Later engineering, tooling, or further project milestones are left strategic and unbooked until this checkpoint is independently demonstrated."
          ],
          "unresolvedUncertainty": [
            "No accepted formal assessment, institution, qualification, syllabus code, or examination cycle is present, so no assessed scope or weighting can be established.",
            "No prerequisite recommendations or resource claims are stated in the supplied section.",
            "No search provider is configured, so public-source verification of the course note was unavailable."
          ],
          "stoppingConditions": [
            "Stop when the report works correctly on the original and changed data files and the malformed-row handling is explained without assistance.",
            "If the report fails on the changed data file, correct the actual errors and re-run; do not add separate practice sets unless a concrete failure shows a specific gap."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The accepted outcome is a small CSV expenses report covering three requested capabilities. A single integrated build-and-demonstrate activity is the smallest useful strategy because it already includes explanation during work, supported application on the original data, and an independent changed-data example. No separate relearning, repeated practice set, or second check is booked before any observed failure, since readiness is unknown but the integrated task can meet the goal cleanly. Later engineering, tooling, or further project milestones remain strategic and unbooked until this checkpoint is independently demonstrated."
}

