  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can correctly choose a valid circuit method, justify the choice, and solve changed circuits with correct answers, without assistance."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "MASTERY",
          "outcome": "I say I have mastered circuit methods, but in my self-reported last check I got four of five changed circuits wrong. Do not ignore this contradiction or certify mastery from my claim; choose proportionate education and a meaningful check.",
          "explanation": "The self-report of mastery is contradicted by the reported 4/5 failure on changed circuits, so mastery cannot be credited. The observed failure is on independent method selection and application, not on a claim of never having learned the methods. Proportionate education therefore starts with a diagnostic on changed circuits to locate which methods and selection rules actually fail, then repairs only the demonstrated gaps through explanation tied to the learner's own errors, supported application, and a final independent changed-circuit check. No separate relearning of every method is booked unless the diagnostic shows the method itself is unknown; that remediation is contingent on the diagnostic result.",
          "recommendedEffort": {
            "lowMinutes": 90,
            "likelyMinutes": 150,
            "highMinutes": 240
          },
          "phases": [
            {
              "localId": "diagnose",
              "title": "Diagnose method-selection failures",
              "outcome": "A concrete record of which circuit methods and selection rules fail on changed circuits, with the learner's actual errors identified.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 60
              },
              "readinessCriterion": "Five changed circuits attempted independently, with each answer and the chosen method recorded and checked against the correct method and result."
            },
            {
              "localId": "repair",
              "title": "Repair demonstrated gaps",
              "outcome": "The learner can explain the selection rule for each failed method and apply it correctly on supported work.",
              "effort": {
                "lowMinutes": 45,
                "likelyMinutes": 75,
                "highMinutes": 120
              },
              "readinessCriterion": "For each method that failed in the diagnostic, the learner explains when it applies and solves a supported example correctly."
            },
            {
              "localId": "verify",
              "title": "Independent changed-circuit check",
              "outcome": "Correct method choice, valid selection reason, and correct solution on changed course-appropriate circuits without assistance.",
              "effort": {
                "lowMinutes": 15,
                "likelyMinutes": 30,
                "highMinutes": 60
              },
              "readinessCriterion": "At least four of five changed circuits solved with the correct method, a valid reason for choosing it, and the correct answer, without assistance."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The full target capability: independent selection and correct application of circuit methods on changed circuits, verified without assistance."
          }
        ],
        "activities": [
          {
            "localId": "diagnostic",
            "outcomeRefs": [
              "diagnose"
            ],
            "scopeRefs": [
              "scope_1"
            ],
